/* @lc app=leetcode id=2662 lang=kotlin */
class Solution { fun minimumCost(start: IntArray, target: IntArray, specialRoads: Array<IntArray>): Int = (listOf(start, target) + specialRoads.flatMap { listOf(intArrayOf(it[0], it[1]), intArrayOf(it[2], it[3])) }).distinctBy { it[0] to it[1] }.let { pts -> IntArray(pts.size) { 1e9.toInt() }.also { it[0] = 0 }.let { dist -> java.util.PriorityQueue<Pair<Int, Int>>(compareBy { it.second }).apply { add(0 to 0) }.let { pq -> generateSequence { if (pq.isNotEmpty()) pq.poll() else null }.forEach { (u, d) -> if (d <= dist[u]) pts.indices.forEach { v -> (Math.Abs(pts[u][0] - pts[v][0]) + Math.abs(pts[u][1] - pts[v][1])).let { direct -> if (d + direct < dist[v]) dist.set(v, d + direct).also { pq.add(v to d + direct) } } }.let { specialRoads.forEach { r -> (Math.abs(pts[u][0] - r[0]) + Math.abs(pts[u][1] - r[1]) + r[4]).let { roadCost -> pts.indexOfFirst { it[0] == r[2] && it[1] == r[3] }.let { v -> if (d + roadCost < dist[v]) dist.set(v, d + roadCost).also { pq.add(v to d + roadCost) } } } } } } dist[pts.indexOfFirst { it[0] == target[0] && it[1] == target[1] }] } } } }